import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷三十二","description":"周易经传集解 - 周易经传集解卷三十二","frontmatter":{"title":"周易经传集解卷三十二","description":"周易经传集解 - 周易经传集解卷三十二"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/033.md","filePath":"zh/classics/jingchuan-jijie/033.md"}'),r={name:"zh/classics/jingchuan-jijie/033.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷三十二",tabindex:"-1"},[n("周易经传集解卷三十二 "),e("a",{class:"header-anchor",href:"#周易经传集解卷三十二","aria-label":"Permalink to “周易经传集解卷三十二”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解卷三十二 ​宋林栗撰序：卦曰：「有过物者必济，故受之以既济。」既济，小过之变也。自过而济，艮变为离，震变为坎，易初、四、五三爻而成也。艮变为离，止乎明也；震变为坎，出乎险也。止乎明，出乎险，卦之所以为「既济」也。「小过、既济，利乎贞」，小过之所以为过而不为济者，初、四、五三爻皆不正，变为既济，则六爻皆正，刚柔当位，是以谓之「既济」也。夫立天下之事者，必有过人之才；革天下之俗者，必有过人之行。过而受之以济，斯其义也。既济：亨小，利贞。初吉终乱。彖曰：「既济亨小」者，亨也。「利贞」，刚柔正而位当也。「初吉」，柔得中也。「终」止则「乱」，其道穷也。下离上坎，成卦曰「既济」者，初为离，二为坎，三为离，四又为坎。离火炎上，三坎水润下，相配而成功，是以谓之「既济」也。然水火之间，必有金木土为之用，然后成「既济」之功。当其成也，金则革矣，土则变也，木则化矣。是故「既济」之时，水火可见，而金木土不可得而见。水火可见，故其六位皆离、坎成形；金木土不可见，故乾、坤、震、巽、艮、兑皆无全象也。或曰：「然则未济之时，亦无六卦之象，将何义以处之？」曰：未济者，水木各居其所而不相值也。金与土木于何而用哉？「既济，亨小，利贞，初吉，终乱，何谓也？」曰：「阳为大，阴为小。坎，阳也；离，阴也。切成于坎，而制在于离。故子曰：既济，亨，小者，亨也。」按文当曰「小亨」。夫兴事造业，开物成务，惟大者为能亨。今小者制之而亨，何也？刚柔之位当，上下之分定也。以阳居刚，以阴居柔，谓之当。九五在上，六二在下，谓定。刚柔当而上下定，是以谓之「利贞」也。然而「初吉终乱」，何也？曰：「先阳而后阴，先治而后乱也。初九之阳，动于既济之初，吉之象也。上六之阴，穷于既济之末，乱之象也。夫存亡治乱，岂有当哉？变而通之，存乎人耳。故子曰：利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。言柔之为道易穷止而不变则乱矣。」或曰：「夫子以初吉为柔得中，而吾子以初九言之，何也？」曰：「初者，阳之造始也；六二者，柔之得中也。阳不造始，则六二何以得其中？柔不得其中，初九何以成其始？文王举其一，夫子明其旨，岂不粲然矣哉？」象曰：水在火上，「既济」，君子以思患而豫防之。水者，「坎」也；火者，「离」也。以水沃火，无余蕴矣。今水在其上，火在其下，不能以相与，则变化成矣，是以为「既济」也。然变化既成，则水火各反其所。苟为不变，则水涸而火炎上也。君子是以思患而预防之也。孟子曰：「有伊尹之志则可；无伊尹之志则□也。」其斯之谓与？杂卦曰：「既济，定也。」「既济」、「未济」以杂「坎」反对而成，其在六爻，以或定或应为义。以阳居刚，以阴居柔，谓之定；以阳居刚、以阴居刚，谓之应。何则？「既济」之时，天下既已平矣。惟君臣上下各守其定分而不相陵犯，斯以为「既济」而已矣。是故「离」下「坎」上，卦之所以为定也；九五、六二，爻之所以为定也。然初与三以阳而居下，四与上以阴而居上，所谓定者，或失之矣。故圣人于初、四两爻，明制治保邦之法；三、上两爻，明夷狄、小人之戒；而于二、五中爻，明君臣夫妇之道，著损益盈虚之理焉。初九：曳其轮，濡其尾，无咎。象曰：「曳其轮」，义「无咎」也。初九，「离」也。以阳居刚，而在一卦之下，应乎六四而承于六二，二爻皆「坎」也，故曰「曳其轮，濡其尾」。「尾」，舟拖也。轮所以行车，尾所以行舟。初六阳刚居于最下，故有「轮」、「尾」之象焉。「离」为舟，「坎」为车，「离」为丽，「坎」为险，故有「曳其轮」、「濡其尾」之象。「既济」诸爻以定为义。今阳刚居下，而取诸曳轮、濡尾者，言其方济之初，则阳刚居下宜矣，故曰「无咎」。车欲进而曳其轮，舟欲浮而濡其尾，宜若有咎矣。然「曳其轮」者，所以制车之迟速，而防其跌也；「濡其尾」者，所以制舟之深浅而防其覆也。又何咎之有哉？故子曰：「曳其轮，义无咎也。」说者因「未济」之彖，必以「尾」为狐尾，则失之于此矣。六二：妇丧其茀，勿逐，七日得。象曰：「七日得」，以中道也。六二，「坎」也。以阴居柔而在下卦之中，应乎九五，而介于初九、九三之间，三爻皆「离」也，故曰「妇丧其茀」。「茀」，车蔽也，妇所以自障。二以居阴柔，有「妇」之象焉。次为舆，为幽。「离」为明，为相见，故有「丧其茀」之象焉。六二、九五之妇，而九三与之相见而无难，以丧其所以自蔽者也。然「既济」之时，上下分定，初九、九三各有其应，二虽居于其间，上应九五，莫之敢犯也，故曰「勿逐，七日得」。三柔而在中，故有「勿逐」之象。易以日言近，以岁言远。七者，天道来复之数也。当「既济」之时，六二守正居中，有应在上，不过七日，必遇其配。遇其配，斯得其蔽矣，奚以逐之为哉？此其「震」六二，丧马勿逐，「七日得」之义同。逐则遂丧之也，何有？天下既定，上下无惊，奸乱之人常伺其隙而乘之。苟为不胜其忿而逐，则失其中道而易其位，乱之所由来也。惟静以持之，则奸谋阻矣。故子曰「七日得，以中道也」。伯禽之誓师曰：「马牛其风，臣妾逋逃，勿敢越逐」者，其定之义乎？君臣之间，夫妇之际，小人间之，说隙易生，可不戒哉？可不重哉？然自二至五，所隔三爻，不言三日而言七日者，「坎」下离上故也。坎下而不能上，离上而不能下，虽欲相过，不亦难乎？卦有六爻，七则变矣。变则六居五而九居三，「坎」上「离」下，应「既济」之象，遇而后得矣。系之七日，不亦宜乎？九三：高宗伐鬼方，三年克之，小人勿用。象曰：「三年克之」，惫也。九三上体为「离」，下体亦为「离」，以阳居刚而在下卦之上，应乎上六，而介于二四之间，三爻皆「坎」也，故曰：「高宗伐鬼方，三年克之。」高宗，中国之贤王，聪明而健者也。鬼方，穷北之小夷，昏迷而难服者也。九二「离」为「明」，故有「高宗」之象。上六「坎」为「幽」，故有「鬼方」之象。离为兵，坎为盗，故有征伐之象。以至明而当至暗，以至强而当至弱，「高宗伐鬼方」之象也。自三至上，所涉三爻，三年之象也。王上居相应之地，而无相与之意，系之伐国，不亦宜乎？去以有商之盛王，伐鬼方氏之小丑，宜若举太山以压鸟卵，不旋踵而殄之矣。然而旷日持久，至于三年而后克之者，谨之至也。语曰：「千金之子，坐不垂堂。」淮南王安有言：「厮与之卒，有一不备而归者，虽得越王之贵，臣窃为大汉羞之。」赵充国有言：「脱有不虞，为夷狄笑，千载不可复。」又曰：「臣恐国家忧累数十年，不二三岁而已。」由是言之，高宗之伐国，三年不为久也。商武之颂曰：「赫赫厥声，濯濯厥灵。寿考且宁，以保我后生。」鬼方既服，而威灵之所被者远矣。四方无事，寿考康宁，而子孙赖之也。然则三年而伐一国，若缓而实速，若怯而实勇，一劳而允逸，暂费而永宁。等讣见效，与夫快心于一战者绝矣。故曰：「小人勿用。」阳为君子，阴为小人。离为君子，坎为小人。六二、六四皆「坎」也，故有小人之象。既济六爻皆定，无相与之意，故有「勿用」之象。说者皆以谓论功行赏，勿用小人，非也。夫信彖者，君子之道；而变诈者，小人之术也。以高宗之盛，而伐鬼方之微，苟期于胜而已，则权谋诡谲，无所不用，不待于三年而克之也。惟夫深谋远虑，以为国家之祸乱，常必由于小人，小人有功，则不可不赏，故宁使远方之未服，不使小人之有功，此高宗之师所以有三年之淹也。或曰：兵，诡道也，所用者皆阻诈之徒也。必欲君子而后用之，不亦迂乎？曰：不然。晋中行穆子次鼓，经年不下。馄间伦曰：「鼓之啬夫，间伦知之，请无疲士夫而豉可得。」穆子不应。左右曰：「不利一战，不伤一卒，而鼓可得，君奚不为？」穆子曰：间伦之为人也，佞而不仁，若使间伦下之，吾不可以不赏。赏之，是赏佞人也。倿人得志，使晋国舍人而为佞，虽得鼓，安用之？此则高宗不用小人之意也。或曰：「然则师之上六，开国成家，小人勿用」，何谓也？曰：大乱之余，群雄并起，有王者作四面而归之。当是之时，来者必纳，岂当问其君子与小人哉？若其有功，鸟得不赏，惟不使之开国成家，以为民害耳。及夫天下既定，上恬下嬉，而远夷之国，有昏迷负国之徒，从未服从，将有岁月耳，讵可急一时之功，而遗后日之患乎？此「师」之上六，「既济」之九三，所以文同而义异也。故子曰：「三年克之，惫。」实按：释文云：「古本惫作备。」备有全师保胜之义焉。若从今本作惫，亦通。盖旷日持久，使鬼方困惫而自服，非与之乎利于锋𫔂之下也。说者皆以三年伐国为高宗之惫，不知权其轻重，校其得丧，讣其久远，乃高宗之所以为贤王也，焉得为惫哉！「明夷」之九三、上六，亦以至明伐暗，其繇曰：「不可疾贞。」与此同义。六四：𦈡有衣袽，终日戒。象曰：「终日戒」，有所疑也。六四上体为「坎」，下体亦为「坎」，以阴居柔，而在上卦之下，应乎初九，而介于三、五之间，三爻皆「离」也，故四「𦈡有衣袽」。旧说皆谓「𦈡」当作「濡」，谓衣之败絮可以塞舟漏也。愚谓不然。涉川而恃漏舟，备舟而恃败絮，殆非防患之道也。按文当曰「衣有𦈡袽」。𦈡，帛边也；袽，絮缊也。四以一阴介二阳之间，故有𦈡袽之象。衣之不戒，或裂而为𦈡，或缊而为袽，又不戒焉，将遂破败而不可纫缝矣，故曰「终日戒」。「离」为日，三爻皆离，故有「终日」之象。「坎」为忧，故有戒惧之象。四应在初，而居二阳之间，初九之所不能无疑也。终日戒惧而后知免矣。故子曰：「终日皆有所疑也。」或曰：「乾为衣而坎称之，何也？」曰：配坤而言，则乾为衣；配离而言，则坎为衣。夫象岂一端而足哉？九五，东邻杀牛，不如西邻之礿祭，实受其福。象曰：「东邻杀牛」，不如西邻之时也；「实受其福」，吉大来也。九五，「离」也。以阳居刚而在上卦之中，应乎六二，而介于四上之间，三爻皆「坎」也，故曰「东邻杀牛，不如西邻之礿祭，实受其福」。说者皆即本卦以求东西邻之义，未有得其说者也。圣人盖以二卦相并为东西邻之象，言既济，东邻也，未济西邻也。既济之为东邻，何也？曰：「东」，阳位也。「西」，阴位也。二卦皆以五为王，则九五之为东邻，六五之为西邻，宜也。九五体「离」，「离」为牛，为戈兵，故有「杀牛」之象。六五体「坎」，「坎」为水，为有孚，故有礿祭之象。夫「礿」，夏祭也。「杀牛」，大祀也。九五所遇皆「坎」，「坎」于时为冬，则杀牛以祭，应其时矣。六五所遇皆「离」，「离」于时为夏，则「酌彼行潦」，亦其时矣。然谓东邻杀牛，不如西邻礿祭者，何也？此则损益盈虚之理也。圣人知祸乱之易平，而盛成之难保，故于此著其戒焉。夫寒往则暑来，小往则大来。「既济」之时，极于九五，圣人之所畏也，故系之以「不如邻」之辞。夫子又从而释之曰：「东邻杀牛，不如西邻之时也，实受其福，吉大来也。」夫以东邻之盛礼，而反不如西邻之薄祭，而反受其福者，遇吉大之来也。然则履富贵之盛，处盈成之极，可不深思而戒惧哉？上六：濡其首，厉。象曰：「濡其首，厉」，何可久也？上六，「坎」也。以阴居柔，而在一卦之上，应乎九三而乘乎九五，二爻皆「离」也，故曰「濡其首，厉」。上居最高，首之象也。初为尾，故上为「首」。「既济」之终，不能极乎刚长，而终之以柔；不能出乎险陷，而下有所丽，是「濡其首」者也。舟船之制，必矫其首而濡及之，是覆弱之形，危亡之象也。故曰「厉」。何则？以柔济刚，以「离」济「坎」，其象则楫之济川是也，其义则人臣之济世是也。舟楫之济川，以既登于岸，然后为「既济」也。人臣之济世，以功成名遂，奉身而退，然后为「克终」也。故「既济」三阴，六二有「丧茀」之疑，六四有「濡袽」之戒。至于上六居卦之终，柔不能变，是功名而不去者也。不为侵君窃国之谋，必为持禄保宠之讣。而三、五之刚明见抑于下，譬犹以济而不登，狎水而玩之，必至于濡其首也。彖之所谓「终止则乱，其道穷者」，非是之谓与？「濡首」之义，与大过上六「过涉灭顶」同。灭顶则已成于㓙，濡首犹可救也，故系之「厉」而已。或曰：然则九三指上六为「鬼方」，何也？曰：九三之明既升，而六犹居其上，在外则为逆命之国，在内则为擅权之臣，故九三有「伐鬼方，勿用小人」之辞，而上六则著其濡首之象，明其祸败可立而须也。故子曰：「濡其首，厉，何可久也。」孔颍达云：「既济」上六濡其首者，始入于难，未没其身也。「未济初六濡其尾者，进不知极，已没其身也。」此皆执文害义。若如此说，则首应在初爻，尾应在上爻矣，安有既「濡其首」而未没其身者乎？序卦曰：「物不可穷也，故受之未济终焉。」「未济」，「既济」之反也。覆而视之，「既济」犹「未济」，「未济」犹「既济」也。「坎」为水，「离」为火，水火相资而成，是也为「既济」；水火各居其所，是以为「未济」也。「既」之为言尽也，已往之辞也；「未」之为言有所待也，方来之辞也。险难已尽而不遂济，终无出险之理，是其时极而道穷可知矣，「未济」则未可穷也。是以「既济」上六直言「濡首」之厉，而「未济」上九两著吉㓙之辞。变通之义，存乎人耳。所以然者，以九居上，阳气存焉；反而居初，「乾」之德也，万物之所以资始也。六五之柔，久而居二，「坤」之德也，万物之所以资生也。故易终于未济，而始于乾坤，所以为循环而不穷者与？故曰：「黄帝、尧、舜通其变，使民不倦；神而化之，与民宜之。易穷则变，变则通，通则久。」「黄帝、尧、舜垂衣裳而天下治，盖取诸乾坤」，斯之谓也。未济，亨。小狐汔济，濡其尾，无攸利。彖曰：「未济，亨」，柔得中也。「小狐汔济」，未出中也。「濡其尾，无攸利」，不续终也。虽不当位，刚柔应也。下坎上离成卦曰「未济」者，初为坎，二为离，三为坎，四又为离。离火炎上，坎水闰下，各居其所而不相逮，是以谓之「未济」也。「未济」何谓也？曰：未济，未可以济之谓也。曰：可以济而言亨者，有可以济之理也。可以济者，有其具也；未可济者，俟其时也。犹之舟楫具而水未至，故系之未济云尔。及夫六五以柔得下应九二，是水至而舟行也。故子曰：「未济，亨，柔得中也。」「小狐汔济，濡其尾，无攸利」，何谓也？曰：阴为小，坎为狐。狐，阴物也，履冰而济者也。汔，几也，几济而未济也。狐之为物，多疑而善虑患，小狐则虑患之未深者也，是以有几而未济之象焉。初六之柔进而上行，至于六五，宜若济矣，然由未出乎中，是以未知其济否也。苟濡其尾，进退不可，斯无攸利矣。故曰：「小狐汔济，未出中也；濡其尾，无攸利，不续终也。」说者或以「汔」为水涸。夫涸而济，犹行陆也，何以明济川之义乎？「井」之彖曰：「汔至，益未繘井。」亦几至之义也。夫子既释彖辞，又从而明之曰：「虽不当位，刚柔应也。」谓诸爻虽不当位，而所以亨者不当位，故「未济」；「刚柔应」，故可以「济」也。夫二卦相反，爻皆有配，而独于未济言应者，谓以阳居柔，以阴居刚。在凡卦，以阴居柔，以阳居刚，则无相逮之情；以阴居刚，以阳居柔，有相与之意。是以既济为定，而未济为应也。或曰：既济无相与之意，而六二、九五有夫妇之辞，何也？曰：应犹成也，定犹怕也。柔上刚下谓之成，刚上柔下谓之恒，刚柔当位谓之定，刚柔相易谓之应。九五为夫，六二为妇，是其定也。二至于「丧其茀」，则五之不应也明矣。然则既济之时，君尊臣卑，其患至于不相应，故子曰：「思患而预防之。」未济之时，上下相与，而君臣之𫝑未定，故「君子以辨物居方」，因其象以救其偏而已矣。象曰：火在水上，「未济」，君子以慎辨物居方。火者，「离」也。水者，「坎」也。离南而坎北，火上而水下，方以类聚，物以群分，自然之理也。水流湿，火就燥，本乎天者亲上，本乎地者亲下，亦各从其类也。君子体之，以辨物而居方，故能使中国四夷不相杂楺，君子小人不相淆乱，至于天下万物，莫不各当其处，皆取诸未济之象也。杂卦曰：「未济，男之穷也。」既济、未济，以离坎相易而成，而未济诸爻，以刚柔始终为义。始于阳者穷乎阴，始乎阴者穷乎阳。是故既济六二为柔得中，则九五亦为刚得中也。未济六五为柔中，则九二亦为刚得中也。未济六五为柔中，柔为之主也。然则以六居上，女之穷也；以九居上，男之穷也。其穷一也，而所以异者，刚柔之不同耳。此既济之所以为穷，而未济之所以为未穷也。何则？以九居上，在乾为亢，在姤为吝。然变而通之，则有生生之理，所谓「枯杨生梯」是也。若女之穷，则穷遂矣。是故未济六三两著「征㓙」、「利涉」之辞；上九兼明「有孚」、「濡首」之义，顾所以处之者如何耳。若夫二、五刚柔得中，故均系之「贞吉」。四以刚之上行，初以柔而下应，故四为「贞吉」而初为「吝」。刚柔之得，固如是矣。或曰：子以既济为定，未济为应；既济为女之穷，未济为男之穷，既有其说矣。不于既济言穷，而未济言应，何也？曰：不于既济言穷者，物不可穷也；不于未济言应者，水火不相射，非若山泽之咸感应以相与也。立言之指，岂苟云乎哉！初六：濡其尾，吝。象曰：「濡其尾」，亦不知极也。初六，坎也。以阴居刚，而在下卦之下，应乎九四而承承于九二，二爻皆离也，故曰：「濡其尾，吝。」坎为水，为狐，初为尾，故有「濡尾」之象。狐之履水，听水以为前却，然直至于「濡其尾」，则羞吝之道也。然彖言「濡其尾，无攸利」，而爻独言「吝」者，以其在卦之初，其失未远，犹可复也，故系之「忧虞」云尔。或曰：既济之初九，其象为离；未济之初六，其象为坎。离之遇坎，与坎之遇离之象宜不同。故「曳其轮」之辞，既济居初，而未济居二；「伐鬼方」之辞，既济居三，而未济居四。其象易，则其辞变也。独初、上二爻「濡尾」、「濡首」之象，二卦同其辞，何也？曰：离以中虚，故其象为舟；坎以隐伏，故其象为狐。舟之济也以冰，冰至则行，冰去则滞。狐之济也以永，永合则度，永泮则陷。是舟之与狐适相反也。故「既济」之初体乎「坎」，「未济」之初体乎「坎」，而象「濡尾」、「濡首」之辞，适相类也。或曰：然则彖言狐而不言舟，何也？曰：书不尽言，言不尽意，舟楫之利也。济不通，二卦之名，盖取诸此，愚智之所同知也，虽不言其名物可也。「狐」，阴类也，非人之所常见，不指其名，将或其象也。此则微里阐幽之意也。夫舟俟水而行，狐听冰而渡，失之仪倾，则有陷溺之忧。是以圣人取之，以明见可而进、知难而退之义。阳为行，阴为止，丽为「离」，「坎」为陷。初九体「离」，行而丽者也；初六体「坎」，止而陷者也。故「既济」之初，「濡尾」为「旡咎」；「未济」之初，「濡尾」为「吝」。舟「濡其尾」，故宜「旡咎」；狐「濡其尾」，则「吝」矣。象异而辞同，事同而功异，其以此与？故曰：「濡其尾，亦不知极也。」见冰之坚以为可度，而不知其有时而泮，是以有「濡尾」之「吝」也。九二：曳其轮，贞吉。象曰：「九二贞吉」，中以行正也。九二，「离」也。以阳居柔而在下卦之中，应乎六五而介于初、三之间，三爻皆「坎」也，故曰「曳其轮」。「坎」，行也，遇险而曳之，所以为安行之道也。或曰：轮者何？曰：「坎」为轮、为曳，故有曳轮之象。轮者，车之所以行在车下也。「既济」在初，而「未济」居二，其所以取象何哉？曰：轮在车下而当其中，故下卦之下与中卦之中，取而象之皆可也。曰：然则「既济」之六二，其不取之何哉？曰：刚则行，柔则止。轮者，所以行也。以六居二，曷为取之哉？故曰「贞吉」。具者，正也。行初之轮，自下而升，仅能免咎而已。九二之轮行乎道，斯得其正矣。曳轮而行，得乎中正，其言吉也宜哉！故子曰：「九二贞吉，中以行正也。」六三：未济，征凶，利涉大川。象曰：「未济，征凶」，位不当也。六三上体为「坎」，下体亦为「坎」，以阴居刚而在下卦之上，应乎上九而介于二、四之间，三爻皆「离」也。故曰：「未济，征凶，利涉大川。」既曰「征凶」，而又曰「利涉」，何也？四三居上下之交、进退之际，方其未可以济，征则凶矣。及其利也，虽大川可涉，而况其小者乎？故凡「未济」而征、利而不涉者，皆凶咎之道也。诗曰：「东方未明，颠倒衣裳。」「未济」而征者也，不能辰夜不夙，则莫利而不涉者也，其咎均矣。故子曰：「未济正凶，位不当也。」为其以六居三，不当其位，是以之其有「未济」之「征」云尔。九四：贞吉，悔亡。震用伐鬼方，三年有赏于大国。象曰：「贞吉，悔亡」，志行也。九四上体为「离」，下体亦为「离」，以阳居柔而在上卦之下，应乎初六而介于三五之间，三爻皆「坎」也，故曰：「贞吉，悔亡。」贞者，正也。以此为正，则志行矣。二卦之象，在取水火相为义矣。夫水火之为性，性不可以相入。水入火而焦，火水入而灭。惟夫离下坎上，相逮而不相射，是以有相济之义。为离下坎上，其卦为「既济」，而九五、六二离上坎下，乃为「未济」也。坎下离上，其卦为「未济」，而六五、九二离下坎乃上为「既济」矣。故「既济」之二五，有「丧茀」「杀牛」之辞，而「未济」之二五，均为「贞吉」也。九四应在初六，而亦谓之「贞吉」，何也？曰：九四秉阳刚之德，体离明之性，阳德上行，离性炎上，承于六五，斯为既济矣。虽有初六之应，六三之比，而不足以易其从五之志，是以系之「贞吉」，而又系之「悔亡」也。故曰：「震用伐鬼方，三年有赏于大国。」九四、初六，既无相得之情，而居相应之地，是「伐国」之象矣。四于既济为三，初于既济为上。「坎」为鬼方，「离」为中国，「坎」为盗，「离」为兵。自四至初，所历三爻，故有「鬼方」「三年」之象，与九三同也。然不三言「贞吉」「悔亡」，何也？曰：阳刚之德，上行者也。以九居三，君道也。三之上行，其不应上六，未可知也。故有「伐鬼方」之辞，又有「勿用小人」之戒。以九居四，臣道也。四之上行，其下不应初六明矣。故「用震于鬼方」，而受赏于大国，至于下比之「悔」，则亡矣。「大国」指中国而言。或谓赏以大国者，非。然二爻「伐鬼方」则同，三为克之，四为「震」可也。曰：三即而伐之，克然后有功。四不之即，取其震惊而已，所谓不战而屈人兵者也。或曰：四取其震惊，则何以三年也？曰：修其守御之备，治其战伐之功，其保吉于此而信威于彼，岂朝夕之功乎？彼暴露师徒，栉风沐雨，犹不以三年为淹，而况为不即之者乎？六五：贞吉，无悔。君子之光，有孚，吉。象曰：「君子之光」，其晖吉也。六五，「坎」也，以阴居刚而在上卦之中，应乎九二而介于四上之间，五爻皆「离」也，故曰「贞吉，无咎」。四之应在初，故先悔而后亡；五之应在二，故「贞吉」之而「无悔」矣，故曰「君子之光，有孚吉」。「坎」为有孚，「离」为光明。光者，德之发于外者也；孚者，德之感于内者也。六五中行而所遇皆离，德之发于外者然也。下有九二，是其正应，德之感于内者然也。柔得尊位大中，而上下应之，是则无咎而有辉光者也。故系以「光孚」之「吉」为「贞吉」者，言其中正以相与，如是则吉也。「孚吉」者，言其充实而孚，光辉见于成功者如是也。所以然者，当未济之时，而六五得中，成既济之象，其内孚而外光，不亦宜乎？故子曰：「君子之光，其辉吉也。」晖者，光之散，言九二、九四、上九三爻皆离，则光晖之所被者远矣。或曰：「六五既济矣，而彖言汔济，未出中之辞，何也？」曰：「既济之终，犹不遂济，未济六五水至舟行」矣，其济之与否，固未可知也。「小狐汔济」，应其象也。上九，有孚于饮酒，无咎。濡其首，有孚失是。象曰：「饮酒」「濡首」，亦不知节也。上九，「离」也，以阳居柔，而在一卦之上，应乎六三而乘乎六五，二爻皆「坎」也，故曰：「有孚于饮酒，无咎。」坎为有，乎为酒，离中虚，饮酒之象。夫人相与期会饮酒，亦不可以「无孚」。其在需曰「需于酒食」是也。饮食燕乐而不失其孚，斯为无咎矣，故曰：「濡其首，有孚失是。」上为首，「坎」为水，故有「濡首」之象。至于「濡其首」而言其「孚」，则失之矣。夫饮酒者，实乐之事也；濡首者，陷溺之形也。以宴乐之事而有陷溺之形，智者之所不为，而尾生之所以为信者也。故子曰：「濡者亦不知节也。」节犹时也。东方未明之诗曰：「不能辰夜，不夙则莫」，而序以为「刺无节」，与此意同。或曰：既济上六以阴而体坎，未济上九以阳而体离，均谓之濡首，何也？曰：既济上六柔而止也，未济上九刚而动也。柔而止者，既济而不济，至于濡其首也；刚而动者，未可以济而必济，至于濡其首也。圣人不能先时，亦不失时，未可为而为之，与可为而不为，其败均之。方其利涉也，虽饮酒之间，暇而不失其孚，夫何咎之有焉？及其征凶也，苟狥其象而不顾濡首之患，斯之谓失矣。子曰：「信近于义，言可复也」，其斯之谓与！周易经传集解卷三十二",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
